WITH rollup_totals AS (SELECT d.country, d.device, a.page, COUNT(*) AS num_rows, MAX(a.duration_sec) AS max_duration_sec, GROUPING_ID() AS gid FROM web_events a LEFT JOIN sessions d ON a.session_id = d.id GROUP BY GROUPING SETS ((d.country, d.device, a.page), (d.country, d.device), (d.country), ())) SELECT country, device, page, max_duration_sec, gid, CASE WHEN device RLIKE '^(desktop|tablet)$' THEN 'GROUP_B' WHEN device RLIKE '^(mobile)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS device_zone FROM rollup_totals
